#!/usr/bin/env python3
"""One-time GMC registration import script. Run on Render Shell."""
import os, json, gzip, base64, psycopg2, psycopg2.extras
from datetime import datetime

DATA = """"""

def main():
    rows = json.loads(gzip.decompress(base64.b64decode(DATA)))
    conn = psycopg2.connect(os.environ['DATABASE_URL'], cursor_factory=psycopg2.extras.RealDictCursor)
    cur = conn.cursor()
    imported = updated = skipped = 0
    for row in rows:
        candidate = row.get('Enter Candidate Name', '').strip()
        if not candidate:
            skipped += 1
            continue
        parts = candidate.rsplit(' - ', 1)
        reg_num = parts[1].strip() if len(parts) == 2 else ''
        if not reg_num:
            skipped += 1
            continue
        cur.execute('SELECT registration_number FROM plab_clients WHERE registration_number = %s', (reg_num,))
        if not cur.fetchone():
            skipped += 1
            continue
        g = lambda k: row.get(k, '').strip()
        def parse_date(v):
            v = v.strip() if v else ''
            if not v:
                return ''
            for fmt in ('%Y-%m-%d', '%d-%b-%Y', '%d/%m/%Y', '%Y-%m-%d %H:%M:%S'):
                try:
                    return datetime.strptime(v, fmt).strftime('%Y-%m-%d')
                except ValueError:
                    continue
            return v
        gmc_ref = g('GMC Reference Number')
        login_pwd = g('Login Pwd')
        sq = g('Secret Question 1')
        sa = g('Secret Answer')
        gmc_setup = g('GMC Setup')
        reg_date = parse_date(g('Registration Date'))
        eng_exam = g('English Exam')
        exam_date = parse_date(g('Exam Date'))
        eng_expiry = parse_date(g('English Result Expiry Date'))
        license_val = g('License') or g('License ')
        license_date = parse_date(g('License Received Date'))
        candidate_email = g('Candidate Email')
        mobile_number = g('Mobile Number')
        
        cur.execute('SELECT id FROM ops_gmc_registration WHERE registration_number = %s', (reg_num,))
        exists = cur.fetchone()
        if exists:
            cur.execute("""UPDATE ops_gmc_registration SET
                gmc_reference_number=%s, login_pwd=%s,
                secret_question=%s, secret_answer=%s,
                gmc_setup=%s, registration_date=%s,
                english_exam=%s, exam_date=%s, english_result_expiry_date=%s,
                license=%s, license_received_date=%s,
                candidate_email=%s, mobile_number=%s,
                updated_at=%s WHERE id=%s""", (
                gmc_ref, login_pwd, sq, sa, gmc_setup, reg_date,
                eng_exam, exam_date, eng_expiry, license_val, license_date,
                candidate_email, mobile_number,
                datetime.now(), exists['id']
            ))
            updated += 1
        else:
            cur.execute("""INSERT INTO ops_gmc_registration (
                registration_number, gmc_reference_number, login_pwd,
                secret_question, secret_answer,
                gmc_setup, registration_date,
                english_exam, exam_date, english_result_expiry_date,
                license, license_received_date,
                candidate_email, mobile_number,
                created_by
            ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", (
                reg_num, gmc_ref, login_pwd, sq, sa, gmc_setup, reg_date,
                eng_exam, exam_date, eng_expiry, license_val, license_date,
                candidate_email, mobile_number, 0
            ))
            imported += 1
    conn.commit()
    cur.close()
    conn.close()
    print(f'GMC: {imported} new, {updated} updated, {skipped} skipped')
    print(f'Total GMC: {imported + updated + skipped}')

if __name__ == '__main__':
    main()
